body='<nav aria-label="四页切换">'+''.join(f'<a href="#{k}" data-page="{k}">{i:02} {t}</a>' for i,(k,t) in enumerate([('cover','封面'),('anatomy','字段解剖'),('register','编号登记'),('time','时间核对')],1))+'</nav><div class="status">精密工业 · 技术出版候选｜原效果评价：差／适配二级｜不自动升等</div><main>'
body+='<section class="page" id="cover"><p class="meta">精密工业 · 技术出版研究</p><div class="cover-grid"><div><div class="bands">'+e('title-first','重新看见','h1')+e('title-second','岸线','p')+'</div>'+e('subtitle','先明确关系，再填写记录。','p','subtitle')+'<dl class="facts"><dt>观察点设定</dt><dd>12个；位置待定</dd><dt>记录轮次</dt><dd>3轮；分配待定</dd><dt>时间设定</dt><dd>30分钟；适用范围待定</dd></dl></div><aside class="cover-info"><p class="orange">资料性质</p><p class="kind">计划说明</p>'+e('cover-description','点位、轮次与时间的定义尚未完成。','p')+'<div class="cover-links"><a href="#anatomy" data-page="anatomy">字段示意 02</a><a href="#register" data-page="register">点位索引 03</a><a href="#time" data-page="time">时间核对 04</a></div></aside></div>'+foot('01')+'</section>'
fields=[('对象编号','待指定','点位用P前缀区分。没有指定具体对象时，不自动填入P01。'),('轮次标签','待指定','R1–R3是计划轮次标签。它们不表示已完成，也不自动与每个点位配对。'),('时间范围','待明确','30分钟的适用范围待定；这里保留未明确状态。'),('观察描述','暂无实测内容','只有实际获得的观察内容才能写进记录；本示意没有测量或观察结果。'),('资料出处','暂无现场资料','出处应能追溯；没有现场资料时，不编日期、照片编号或仪器信息。')]
body+='<section class="page" id="anatomy"><h2>记录信息放在哪里</h2><p>原创字段结构示意，尚非采用中的记录表，也不是现场记录。</p><div class="anatomy"><div class="anatomy-head">字段结构示意</div>'
for i,(name,status,note) in enumerate(fields,1):body+=f'<section class="field-pair {"right" if i>3 else ""}"><div class="field"><span class="code">N{i}</span><span>'+e(f'field-{i}',name,'span','field-name')+e(f'status-{i}',status,'span','field-status')+f'</span></div><p class="field-note"><span class="note-heading"><span class="code">N{i}</span> · '+e(f'field-{i}',name)+'</span>'+e(f'note-{i}',note)+( ' <a href="#time" data-page="time">见04页时间核对</a>。' if i==3 else '')+'</p><span class="connector" aria-hidden="true"></span></section>'
body+='</div><p class="anatomy-caption">N1–N5为注释编号。示意只解释字段分工，不证明记录方法已经成立。</p>'+foot('02')+'</section>'
body+='<section class="page" id="register"><h2>先给对象编号</h2><p>P表示点位。以下仅列占位编号，名称和位置尚未确定。</p><div class="register-columns">'
for group in range(3):
 body+=f'<section><p class="range">P{group*4+1:02}–P{group*4+4:02}</p><ol class="point-list">'
 for n in range(group*4+1,group*4+5):body+=f'<li><span class="point-code">P{n:02}</span><span class="point-text">'+e(f'point-{n}','名称待定')+'<span>位置待定</span></span></li>'
 body+='</ol></section>'
body+='</div><div class="round-band"><h3>另一个编号系统：R表示轮次</h3><p>轮次标签：R1、R2、R3；与上方点位尚未建立分配关系。</p></div><p class="register-warning">编号列仅方便查找，不表示点位的空间排列、优先级或三组分区。阅读顺序P01至P12。</p>'+foot('03')+'</section>'
body+='<section class="page" id="time"><h2>30分钟，指什么范围？</h2><p>时间设定已给出，适用范围待定。</p><div class="time-layout"><div class="existing"><h3>现有表述</h3><p class="statement">时间设定30分钟</p><p>范围未说明</p></div><ul class="branches">'
for i,(q,t) in enumerate([('适用于单点？','需要说明是每个点位的时长，还是某一指定点位的时长。'),('适用于单轮？','需要说明一轮的范围，以及该时间是否适用于各轮。'),('适用于整次活动？','需要说明起止边界；目前不能分摊到点位或轮次。')],1):body+='<li><h3>'+q+'</h3>'+e(f'branch-{i}',t,'p')+'</li>'
body+='</ul><aside class="shared-limit"><h3>当前未确定</h3>'+e('time-limit','这三项是待澄清的候选解释，并不穷尽所有可能；本图没有作出选择。','p')+'</aside></div><p class="time-warning">确认范围之前，不计算每轮10分钟，不推导每点30分钟。点位数量和轮次数量不能消除这项歧义。</p><p class="equivalent">已有时间设定30分钟，范围待定；可澄清是否对应单点、单轮、整次活动或其他范围。尚无选择或推导。</p>'+foot('04')+'</section></main>'
body+='''<details class="editor"><summary>编辑与导出</summary><div class="tools"><button id="edit" aria-pressed="false">编辑文字</button><button id="overview" aria-pressed="false">四页并看</button><button id="mono" aria-pressed="false">黑白检查</button><button id="reset">恢复初始版本</button></div><div class="tools"><label>主墨 <input type="color" id="ink" value="#20221f"></label><label>强调色 <input type="color" id="red" value="#a34b25"></label><button id="json-export">下载编辑数据 JSON</button><button id="html-export">下载可编辑 HTML</button><label>导入 JSON <input id="json-import" type="file" accept=".json,application/json"></label></div><p class="tool-note">可改标题、说明、字段名及示意状态、点位显示名、分支文字。N字段名与旁注标题同步，P/N/R引用键固定；改显示名不改身份。资料仍是虚构示意，修改文字不会生成实测结果。线条由版面边界关联，随行高变化；小屏取消引线、逐字段紧邻注释。</p><p id="edit-status" role="status" class="tool-note">默认静态，无动画，暂停不适用。系统减少动效不影响内容与功能。</p><p class="tool-note">系统字体未打包；自定颜色需另查对比度。200%缩放、打印与跨平台字体另验。</p></details><div class="editor-footer">PI-PUB-01 · 原创技术出版适配，未复制历史作品或暗示工程认证。</div>'''
model={'schemaVersion':1,'designVersion':'PI-PUB-01','qualityTag':'差','adaptationLevel':2,'candidate':True,'text':{},'colors':{'ink':'#20221f','red':'#a34b25'}}
